// Exam A2 texts from egzaminu_temos_a2.html. Do not edit by hand.
export const examTextsById = {
  'apie-mane': [
    { id: 'p1', lt: "Mano vardas Polina Sokol, man keturiasdešimt vieneri metai. Mūsų šeima atvyko gyventi ir dirbti į Lietuvą prieš ketverius metus. Aš gimiau ir užaugau Baltarusijos Respublikos sostinėje – Minske. Dabar gyvenu Vilniuje. Mano gimtoji kalba – rusų. Aš laisvai kalbu baltarusiškai ir angliškai. Mokiausi taip pat vokiečių kalbos, bet šiuo metu jos nesinaudoju. Pernai pradėjau mokytis lietuvių kalbos. Man labai svarbu mokėti valstybinę kalbą tos šalies, kurioje gyvenu. Lietuvių kalba yra melodinga. Man patinka mokytis lietuvių kalbos." },
    { id: 'p2', lt: "Mano šeima nėra didelė. Turiu vyrą Sergėjų, dukrą Aną ir sūnų Piotrą. Mes visi gyvename šiuolaikiškame bute gražiame Pašilaičių rajone. Tai jaukus rajonas su parkais ir žaidimų aikštelėmis, jame patogu auginti vaikus. Žiemą mėgstame leistis su rogutėmis nuo kalnelio šalia mūsų namų." },
    { id: 'p3', lt: "Mano vyras dirba programuotoju lietuvių įmonėje. Jam labai patinka jo darbas. Jis dirba tarptautinėje komandoje, bendrauja anglų kalba ir mokosi kalbėti lietuviškai." },
    { id: 'p4', lt: "Mūsų vaikai mokosi mokykloje. Jie mėgsta plaukioti, žiemą čiuožinėti pačiūžomis, o vasarą jodinėti žirgais. Groja pianinu ir žaidžia „PlayStation“. Mano dukra mėgsta siuvinėti ir velti iš vilnos, o sūnus mėgsta konstruoti „Lego“." },
    { id: 'p5', lt: "Baltarusijoje liko gyventi mano mama, tėvas ir jo žmona bei mano jaunesnioji sesuo. Mano tėvai yra pensininkai. Jie gyvena aktyviai – toliau dirba ir sportuoja. Mano tėtis mėgsta žvejoti. Vasarą jie daug laiko praleidžia sode, kur augina vaismedžius ir daržoves." },
    { id: 'p6', lt: "Mano sesuo yra dvejais metais jaunesnė už mane. Ji nėra ištekėjusi. Ji dirba vadybininke Baltarusijos įmonėje." },
    { id: 'p7', lt: "Aš dirbu nedidelėje įmonėje. Pagal pirmąją specialybę esu grafikos dizainerė. Daug metų dirbau reklamos srityje. Darbo metu išstudijavau marketingą. Dabar mane domina ekonomika. Planuoju įgyti antrą aukštąjį išsilavinimą. Man patinka ekonomika, nes ji tyrinėja visas įmanomas žmonių gyvenimo sritis." },
    { id: 'p8', lt: "Laisvalaikiu mėgstu pasakoti istorijas ir skelbti jas socialiniuose tinkluose, fotografuoti ir filmuoti. Prieš gimstant vaikams dirbau profesionalia reklamos fotografe. Mėgstu skaityti knygas ir mokslinius straipsnius, klausytis muzikos, žiūrėti filmus, vaikščioti su vaikais, sportuoti. Mėgstu bėgioti, plaukioti, daryti mankštą ir stiprinti nugarą." },
    { id: 'p9', lt: "Mano mėgstamiausi patiekalai – bulviniai blynai su lašiša, šviežių daržovių salotos ir desertai be cukraus. Mėgstu keliauti ir noriu aplankyti visas Europos šalis. Svajoju du kartus per metus atostogauti prie jūros. Kartą per metus mūsų šeima būtinai vyksta į Palangą. Mums labai patinka vaikščioti pajūriu ir kvėpuoti gaiviu jūros oru." },
    { id: 'p10', lt: "Lietuvių kalba man yra šiek tiek sudėtinga, bet aš stengiuosi mokytis naujų žodžių ir gramatikos. Noriu geriau suprasti lietuvių kultūrą ir bendrauti su žmonėmis lietuviškai." },
  ],
  'mano-namai': [
    { id: 'p1', lt: "Mano šeima gyvena šiuolaikiškame keturių kambarių bute gražiame Pašilaičių rajone. Tai tvarkingas ir jaukus Vilniaus rajonas su parkais ir žaidimų aikštelėmis, jame patogu auginti vaikus. Žiemą mėgstame čiuožti nuo kalnelio šalia mūsų namų." },
    { id: 'p2', lt: "Mūsų bute yra vienas miegamasis, du vaikų kambariai, du vonios kambariai ir svetainė su virtuve bendroje erdvėje. Turime nedidelį balkoną, kuriame vasarą patogu džiovinti skalbinius, o žiemą laikyti kalėdinę eglutę. Kambariai mūsų bute nėra dideli. Kiekviename iš jų yra lova, rašomasis stalas ir nedidelė spinta. Turiu dukrą ir sūnų, todėl kiekvienas vaikas turi savo kambarį." },
    { id: 'p3', lt: "Pats erdviausias kambarys saulėtoje pusėje yra mūsų dukros. Pro langus matomas kiemas su sporto aikštele. Kambaryje laikomi jos mėgstamiausi žaislai. Stovi lentyna su knygomis. Dukra labai mėgsta skaityti. Kiekvieną mėnesį perkame naujų knygų, o senas atiduodame pažįstamiems, kurių vaikai yra jaunesni." },
    { id: 'p4', lt: "Sūnaus kambarys yra šiaurinėje namo pusėje. Pro jo langus matoma automobilių stovėjimo aikštelė prie namo. Jam patinka jo kambarys. Jame yra mėgstamiausių žaislų ir knygų. Yra drabužių spinta. Sūnui patinka gražūs drabužiai. Mokykloje jis dėvi marškinėlius ir džemperius su mokyklos emblema. Laisvalaikiu jis dėvi ryškius drabužius su mėgstamų žaidimų ir animacinių filmų personažais." },
    { id: 'p5', lt: "Mūsų miegamajame mes su vyru ilsimės, skaitome knygas ir dirbame kompiuteriu. Čia turime nedidelę lentyną, kurioje laikome svarbius dokumentus. Yra dvigulė lova, rašomasis stalas ir kėdė." },
    { id: 'p6', lt: "Svetainė – tai vieta, kur susirenka visa šeima. Čia stovi didelė sofa. Mėgstame kartu žiūrėti amerikiečių serialus ir dokumentinius filmus apie keliones ir istoriją. Vakare susėdame prie apvalaus stalo ir vakarieniaujame. Mėgstame daržovių ir kruopų patiekalus. Desertui aš kepu bananų keksą arba vyras kepa blynus. Mėgstame valgyti blynus su grietine ir uogiene." },
    { id: 'p7', lt: "Mūsų virtuvė yra maža, bet patogi. Čia yra viskas, ko reikia visos šeimos maistui ruošti. Neseniai nusipirkome didelį šaldytuvą su šaldikliu. Kiekvieną sekmadienį nusiperkame maisto produktų visai savaitei: šviežių daržovių, vaisių ir šaldytų pusgaminių, kad galėtume greitai paruošti vakarienę. Virtuvės spintelėse laikomi puodai, keptuvės, lėkštės, puodeliai, stiklinės, šaukštai, šakutės, peiliai." },
    { id: 'p8', lt: "Mūsų namas yra šalia parko. Netoliese yra „Rimi“, „Maxima“ ir „Lidl“ parduotuvės. Yra troleibusų stotelė, iš kurios greitai galima nuvykti į miesto centrą. Man patinka eiti pasivaikščioti greta namų, nes čia gražu, saugu ir daug medžių." },
    { id: 'p9', lt: "Labai myliu mūsų butą ir mūsų rajoną. Čia jaučiuosi patogiai ir jaukiai!" },
  ],
  'laisvalaikis': [
    { id: 'p1', lt: "Turiu labai mažai laisvo laiko. Aš turiu du vaikus. Daug laisvo nuo darbo laiko praleidžiu su vaikais. Mums patinka vaikščioti parke, važinėtis riedučiais, pietauti kavinėje, plaukioti baseine, čiuožinėti kalneliais vandens parke." },
    { id: 'p2', lt: "Vasarą dažnai keliaujame į kitus Lietuvos miestus. Susipažįstame su Lietuvos kultūra. Buvome Trakuose. Mums patiko pilis ir ežerai aplink pilį. Plaukiojome baidarėmis ir vandens dviračiais." },
    { id: 'p3', lt: "Kartą per metus vykstame į Anykščius. Ten daug pramogų šeimai. Gruodį važiavome kalėdiniu traukinuku ir šokome su kalėdiniu nykštuku. Vasarą važiuosime pasivaikščioti basomis sveikatingumo taku ir stebėsime medžius iš aukštai." },
    { id: 'p4', lt: "Vaikams patinka vandens batutai Elektrėnuose. Važinėjame tenai vasarą." },
    { id: 'p5', lt: "Kiekvieną savaitgalį mes važiuojame į Suderve. Ten yra Vaigeliškių žirgynas. Vaikai jodinėja arkliais, o aš filmuoju gražius vaizdus ir fotografuoju prisiminimui." },
    { id: 'p6', lt: "Kartą per metus keliaujame į Musninkus. Vaikštome po mišką, pietaujame tradicinėje žydų kavinėje ir tyrinėjame garsųjį urvą." },
    { id: 'p7', lt: "Tris kartus per vasarą apsilankome Kernavėje. Ten yra įdomiausias Lietuvos etnografinis muziejus ir vyksta festivaliai: Joninių šventė, viduramžių kultūros festivalis ir amatininkų festivalis. Mes kviečiame tenai visus draugus." },
    { id: 'p8', lt: "Kai pasiliekame Vilniuje ir niekur nevažiuojame, einame į Vingio parką. Labiausiai mums patinka važinėtis šeimos dviračiu – tai labai linksma! Parke vaikščioja daug žmonių su šunimis. Mano dukra svajoja turėti špicų veislės šuniuką. Mes taupome pinigus, kad galėtume jį nusipirkti ir juo rūpintis." },
    { id: 'p9', lt: "Kai lieku viena ir turiu laisvo laiko, mėgstu pamiegoti. Klausausi meditacijos ir užmiegu. Mėgstu skaityti istorinius prancūzų romanus – Hugo, Morua, Diuma. Aš mėgstu šokti ir klausytis populiariosios muzikos. Kai jaučiuosi liūdnai, klausausi hardcore muzikos. Mėgstu žiūrėti filmus ir serialus apie tikrąjį įvairių pasaulio šalių gyvenimą – apie paprastų žmonių džiaugsmus ir problemas. Aš dažnai verkiu, kai žiūriu meninius filmus." },
    { id: 'p10', lt: "Kartais susitinku su draugėmis kavinėje. Mes geriame arbatą arba kavą ir kalbamės." },
    { id: 'p11', lt: "Labai svarbu turėti laisvo laiko. Jis leidžia man pailsėti ir aš jaučiuosi laiminga." },
  ],
  'hobis': [
    { id: 'p1', lt: "Aš turiu keletą hobių. Laisvalaikiu mėgstu užsiimti tuo, kas man įdomu." },
    { id: 'p2', lt: "Mėgstu skaityti knygas. Man patinka skaityti istorinius prancūzų Hugo, Morua, Diuma romanus." },
    { id: 'p3', lt: "Dar vienas mano hobis – fotografija. Iki vaikų gimimo buvau profesionali fotografė. Fotografavau vestuves ir reportažus apie kultūrinius bei politinius renginius. Dariau reklamines nuotraukas, prekių nuotraukas katalogams. Vasarą botanikos sode fotografavau šeimas ir dariau individualius portretus." },
    { id: 'p4', lt: "Dabar turiu du vaikus, ir fotografuoju tik juos." },
    { id: 'p5', lt: "Mėgstu šokti ir klausytis populiarios muzikos. Kai man būna liūdna, klausausi hardcore muzikos." },
    { id: 'p6', lt: "Laisvadieniais važinėju dviračiu arba bėgioju parke. Tai padeda man atsipalaiduoti ir pakvėpuoti grynu oru." },
    { id: 'p7', lt: "Kartais piešiu. Esu profesionali dailininkė. Baigiau Baltarusijos valstybinę dailės akademiją. Tačiau iš piešimo negaliu pakankamai užsidirbti, todėl tapyba ir piešimas tapo mano hobiu." },
    { id: 'p8', lt: "Kartą per mėnesį lankausi moterų klube. Klube susipažįstu su naujais žmonėmis. Mes kartu vakarieniaujame ir diskutuojame svarbiomis socialinėmis temomis." },
    { id: 'p9', lt: "Man labai patinka vaikščioti į masažą. Mėgstu rūpintis savimi – lankytis pas kirpėją, darytis manikiūrą ir kosmetines procedūras." },
    { id: 'p10', lt: "Mėgstu lankytis muziejuose. Man labai patinka šiuolaikinio meno muziejus MO – tiek jo pastatas, tiek įvairios ekspozicijos. Taip pat mėgstu Nacionalinio dailės muziejaus pastatą ir ekspoziciją – jame galima pamatyti klasikinių ir šiuolaikinių Lietuvos dailininkų kūrinius. Aš labai myliu meną." },
    { id: 'p11', lt: "Hobis daro mano gyvenimą įdomesnį. Manau, kad kiekvienas žmogus turėtų užsiimti tuo, kas teikia jam džiaugsmą." },
  ],
  'profesija': [
    { id: 'p1', lt: "Aš dirbu grafikos dizainere. Tai įdomi ir kūrybiška profesija. Kuriu reklamą, logotipus, reklaminius skydelius ir svetainių maketus. Man patinka mano darbas, nes galiu pasinaudoti fantazija ir kurti gražius dalykus." },
    { id: 'p2', lt: "Aš moku dirbti su daugybe kompiuterinių programų, kurios padeda kurti modernius projektus. Laisvai kalbu angliškai, todėl greitai išmokstu dirbti su nauja programa, nes galiu žiūrėti originalius mokomuosius vaizdo įrašus." },
    { id: 'p3', lt: "Mano profesija leidžia man dirbti su žmonėmis iš įvairių pasaulio šalių. Man patinka dalyvauti profesinėse konferencijose Vilniuje ir keliauti į kitas šalis, kad susipažinčiau su kolegomis, sužinočiau apie naujas technologijas, įgyčiau naujos profesinės patirties." },
    { id: 'p4', lt: "Mano darbo diena prasideda aštuntą valandą ryto, iškart po to, kai nuvežu vaikus į mokyklą. Pirmiausia patikrinu paštą ir suplanuoju dienos darbus. Po to dirbu su įvairiais projektais. Kartais kuriu naujus dizainus, o kartais taisau senus." },
    { id: 'p5', lt: "13:00 (pirmą / tryliktą valandą) baigiu darbą ir pradedu gaminti pietus. Antrą valandą iš mokyklos grįžta mano dukra, ji yra vyresnė už sūnų. Mes pietaujame kartu. Po to ji pradeda ruošti pamokas, o aš toliau dirbu prie kompiuterio." },
    { id: 'p6', lt: "Kartais po pietų turiu susitikimų su klientais. Aptariame projektus ir renkamės geriausią variantą." },
    { id: 'p7', lt: "Ketvirtą valandą važiuoju pasiimti jaunesniojo vaiko – sūnaus, kad nuvežčiau jį į būrelius. Jis lanko parkūrą, futbolą ir robotiką. Dukra čiuožinėja. Ji važiuoja į čiuožyklą savarankiškai." },
    { id: 'p8', lt: "Aštuntą valandą vakaro visa mūsų šeima susitinka namuose. Gaminame vakarienę, tikriname vaikų namų darbus, aptarinėjame, kaip praėjo diena. Kartais visus šiuos reikalus sutvarko vyras. O aš važiuoju į biurą padirbėti iki vėlyvo vakaro, kad kuo greičiau užbaigčiau projektą." },
    { id: 'p9', lt: "Aš myliu savo profesiją, nes ji suteikia man galimybių tobulėti ir mokytis naujų dalykų." },
  ],
  'buitis': [
    { id: 'p1', lt: "Mano šeima nėra didelė. Turiu vyrą Sergėjų, dukrą Aną (ji vyresnė) ir sūnų Piotrą (jis jaunesnis). Mes gyvename kartu moderniame bute gražiame Pašilaičių rajone. Tai tvarkingas rajonas su parkais ir žaidimų aikštelėmis, jame patogu auginti vaikus. Žiemą mėgstame čiuožti nuo kalno šalia mūsų namų." },
    { id: 'p2', lt: "Turiu labai mažai laisvo laiko ir daug namų ruošos darbų." },
    { id: 'p3', lt: "Kiekvieną rytą pabundu 6:30 (pusę septintos) ryto. Išsivalau dantis, apsirengiu, išgeriu vitamino D ir gaminu pusryčius sūnui. Sūnus mėgsta kiaušinienę ir sumuštinius su dešra. Po to pažadinu vaikus. Dukra nepusryčiauja, apsirengia pati ir išvažiuoja į mokyklą. Padedu sūnui apsirengti ir susiruošti daiktus. Vyras nuveža jį į mokyklą automobiliu. Dukra nenori jų laukti, ji važiuoja pati. Vyras ir sūnus dažnai vėluoja į mokyklą." },
    { id: 'p4', lt: "Tada tvarkau vaikų kambarius. Pakloju lovas ir sudedu daiktus į lentynas." },
    { id: 'p5', lt: "Mano darbo diena prasideda 8 (aštuntą) valandą ryto. Dirbu namie prie kompiuterio ir atsitraukiu tam, kad įdėčiau skalbinius į skalbimo mašiną, išimčiau juos iš skalbimo mašinos, pakabinčiau ant džiovyklos, nuimčiau nuo džiovyklos ir sudėčiau į lentynas." },
    { id: 'p6', lt: "13:00 (pirmą / tryliktą valandą) aš baigiu darbą ir pradedu gaminti pietus. Antrą valandą iš mokyklos grįžta mano vyresnioji. Mes pietaujame kartu. Tada ji pradeda ruošti pamokas, o aš toliau dirbu prie kompiuterio." },
    { id: 'p7', lt: "Kartais turiu laiko padaryti mankštą nugarai stiprinti. Kitą kartą tuo metu plaunu grindis, valau dulkes, laistau gėles." },
    { id: 'p8', lt: "Ketvirtą valandą važiuoju pasiimti jaunesniojo vaiko – sūnaus, kad nuvežčiau jį į būrelius. Kai išeinu iš buto, pasiimu išmesti šiukšles." },
    { id: 'p9', lt: "Aštuntą valandą vakaro visa mūsų šeima susitinka namuose. Gaminame vakarienę, tikriname vaikų namų darbus, aptarinėjame, kaip praėjo diena. Kartais visus šiuos reikalus sutvarko vyras. O aš važiuoju į biurą padirbėti iki vėlyvo vakaro, kad kuo greičiau užbaigčiau projektą." },
    { id: 'p10', lt: "Myliu savo namus ir savo šeimą. Labai mėgstu rūpintis vaikais ir mūsų namais." },
  ],
  'atostogos': [
    { id: 'p1', lt: "Mes su vyru seniai svajojome apie atostogas Maljorkoje. Turime du vaikus, todėl norėjome rasti vietą, kur būtų įdomu ir mums, ir jiems. Prieš mėnesį aviakompanija pasiūlė bilietus į Maljorką su nuolaida. Mes nusipirkome bilietus ir pradėjome planuoti kelionę." },
    { id: 'p2', lt: "Į Maljorką atskrisime liepos mėnesį. Orai jau bus šilti, bet dar ne per karšti. Atskrisime tiesioginiu reisu iš Vilniaus į Maljorkos sostinę Palmą." },
    { id: 'p3', lt: "Dabar turime pasirinkti vietą, kur apsistoti. Mes ieškome viešbučio ar apartamentų su baseinu, vaikų žaidimų aikštele ir netoli paplūdimio. Mes radome keletą gerų variantų skirtinguose Maljorkos miestuose. Savaitgalį planuojame su vaikais aptarti visus variantus ir išsirinkti viešbutį, kuris patiktų visiems." },
    { id: 'p4', lt: "Turime susiplanuoti, ką veiksime Maljorkoje. Norime išsinuomoti automobilį salai apžiūrėti. Norime aplankyti kelis skirtingus paplūdimius. Išsimaudyti šiltoje jūroje ir pasideginti. Planuojame nuvykti į Palmą, apžiūrėti miestą. Norime aplankyti vandens parką, okeanariumą ir zoologijos sodą. Mūsų vaikai niekada nėra matę žirafos, tigro ir zebro. Jie taip pat pamatys dramblį, antilopes ir flamingus. Okeanariume pamatys ryklius, egzotiškas žuvis, koralus, aštuonkojus, medūzas ir jūros vėžlius." },
    { id: 'p5', lt: "Mes esame patyrę keliautojai. Greitai susikrauname lagaminus. Su savimi pasiimsime nedaug daiktų. Svarbu nepamiršti pasiimti asmens dokumentus (pasą arba asmens tapatybės kortelę ir vairuotojo pažymėjimą) ir draudimo liudijimus, smulkių grynųjų, viešbučio rezervacijos patvirtinimą bei žemėlapius, pirmosios pagalbos vaistinėlę, apsauginį kremą ir akinius nuo saulės, kepures ir maudymosi kostiumėlius." },
    { id: 'p6', lt: "Mėgstame pažinti naujas šalis ir miestus, ragauti naują maistą ir bendrauti su naujais žmonėmis. Kiekvienoje kelionėje susipažįstame su naujais draugais. Mūsų vaikai aktyviai mokosi anglų kalbos mokykloje, nes supranta, kad galės bendrauti su vaikais iš įvairių pasaulio šalių." },
    { id: 'p7', lt: "Praėjusią vasarą mes keliavome į Barseloną ir jau mokame keletą žodžių ispanų ir katalonų kalbomis. Kelionei į Maljorką išmoksime dar keletą naudingų žodžių ir frazių." },
    { id: 'p8', lt: "Nekantriai laukiame savo atostogų!" },
  ],
  'draugai': [
    { id: 'p1', lt: "Mūsų šeima atvyko gyventi ir dirbti į Lietuvą prieš ketverius metus. Visi mūsų draugai liko Baltarusijoje. Čia mes susipažinome su daugeliu malonių ir įdomių žmonių. Ir netgi radome tikrų draugų." },
    { id: 'p2', lt: "Kiekvienais metais švenčiame mano dukters gimtadienį kartu su jos klasės draugės šeima. Mergaitės gimė tą pačią dieną. Šios šventės tapo proga susipažinti mūsų šeimoms. Samsonovų šeima yra pabėgėliai iš Ukrainos. Mūsų jaunesni vaikai taip pat gimė tą pačią dieną. Tik mano sūnus metais vyresnis už Aną Samsonovą. Vasarą kartu su vaikais ilsimės prie ežero, važiuojame į festivalius ir šventes." },
    { id: 'p3', lt: "Mano draugė Diana organizuoja moterų bendruomenės susitikimus. Kartą per mėnesį lankau moterų klubo susitikimus. Jau dvejus metus. Moterys susitinka kavinėje darbo dienos pabaigoje. Kiekvieną kartą į susitikimą ateina naujų moterų. Susipažįstame viena su kita. Kiekviena pasakoja apie save, savo pomėgius ir darbą. Tada vakarieniaujame prie bendro stalo. Valgome karštąjį patiekalą ir geriame kavą su desertu. Aš negeriu kavos. Pirmenybę teikiu šaltalankių morsui. Po vakarienės Diana siūlo mums temas diskusijoms 3-4 (trijų-keturių) žmonių grupėje. Svarbių socialinių temų aptarimas padeda moterims geriau susipažinti viena su kita." },
    { id: 'p4', lt: "Taip pat Diana man padeda medicininio ir pensijų draudimo klausimais. Mėgstame kartu papietauti ir aptarti asmeninį gyvenimą bei svarbius reikalus." },
    { id: 'p5', lt: "Mano draugė Nataša, kaip ir aš, atvyko iš Minsko. Kartu mokėmės Baltarusijos valstybinėje menų akademijoje. Nataša labai gera ir visada pasiruošusi padėti. Kartais kartu pasivaikštome po Senamiestį. Ten daug gražių pastatų, jaukių gatvelių ir įdomių vietų. Mes susirandame įdomią jaukią kavinę ir atsipalaiduojame prie kvapnios arbatos puodelio. Nataša mėgsta skaityti knygas ir mes dažnai aptariame perskaitytas knygas." },
    { id: 'p6', lt: "Mes su draugais mėgstame leisti laiką kartu. Palaikome vieni kitus sunkiomis akimirkomis ir džiaugiamės pasiekimais." },
    { id: 'p7', lt: "Labai vertinu savo draugystę su Diana ir Nataša. Jos yra svarbi mano gyvenimo dalis." },
  ],
  'miestas': [
    { id: 'p1', lt: "Mūsų šeima atvyko gyventi ir dirbti į Lietuvą prieš ketverius metus. Aš gimiau ir užaugau Baltarusijos Respublikos sostinėje Minske. Dabar gyvenu Vilniuje. Mes gyvename moderniame bute gražiame Pašilaičių rajone. Tai tvarkingas rajonas su parkais ir žaidimų aikštelėmis, jame patogu auginti vaikus. Žiemą mėgstame čiuožinėti nuo kalno prie mūsų namų." },
    { id: 'p2', lt: "Vilnius yra Lietuvos sostinė. Tai gražus senovinis miestas. Kada jis įkurtas, tiksliai nežinoma, bet Vilnius pirmą kartą paminėtas Lietuvos didžiojo kunigaikščio Gedimino 1323 (tūkstantis trys šimtai dvidešimt trečiųjų) metų laiške, todėl šie metai laikomi Vilniaus įkūrimo data. Gediminas perkėlė Lietuvos sostinę iš Trakų į Vilnių. Centrinėje Vilniaus aikštėje prie Katedros yra kunigaikščio Gedimino paminklas. Šalia yra Lietuvos nacionalinis muziejus, Gedimino pilis ir Lietuvos valdovų rūmai." },
    { id: 'p3', lt: "Vilniuje yra daug muziejų ir teatrų. Mėgstu lankytis muziejuose. Mano mėgstamiausias muziejus yra Modernaus meno centras MO. Jis pastatytas buvusio sovietinio kino teatro „Lietuva“ vietoje. Tai labai populiari vieta tiek tarp miestiečių, tiek tarp turistų. Jame vyksta įdomios parodos. Labiausiai man patiko jaunųjų Lietuvos menininkų konkursinė paroda." },
    { id: 'p4', lt: "Vilniuje yra keletas gerų teatrų. Bet dar nebuvau nei viename spektaklyje. Mano vaikai kartu su savo klasiokais kartą per pusmetį eina į vaikų spektaklius Lietuvos arba Rusų dramos teatre." },
    { id: 'p5', lt: "Aš dirbu biure miesto centre, Konstitucijos prospekte. Mane įkvepia šio prospekto pavadinimas. Pro langą matau Neries upės krantinę. Matau bažnyčią Lukiškių aikštėje ir Nacionalinę dailės galeriją." },
    { id: 'p6', lt: "Man patinka mano darbas. Turiu gerų kolegų. Jie kalba lietuviškai ir rusiškai. Aš mokausi lietuvių kalbos ir bendrauju lietuviškai, kai tik galiu. Po darbo dažnai einu pasivaikščioti po miestą arba susitinku su draugais kavinėje. Vilniuje yra daug kavinių ir restoranų. Man patinka lietuviška virtuvė. Mano mėgstamiausias patiekalas yra bulviniai blynai su lašiša. Vasarą su vaikais mėgstame gerti girą, o žiemą – vyšnių ar spanguolių kisielių." },
    { id: 'p7', lt: "Vilniuje yra daug istorinių pastatų, bažnyčių ir muziejų. Bet labiausiai man patinka Vilniaus parkai ir ežerai aplink miestą. Vasarą su vaikais važiuojame maudytis Gelūžės ežere. Ten yra mūsų mėgstamas paplūdimys su kaukazinės slyvos medžiu. Šio medžio šešėlyje ilsimės." },
    { id: 'p8', lt: "Vilniuje yra daug parkų ir skverų. Mėgstu pasivaikščioti Vingio parke. Ten daug medžių ir gėlių. Vasarą mūsų šeima mėgsta važinėti šeimyniniu dviračiu. Tai labai smagu. Parke vaikšto daug žmonių su šunimis. Mano dukra svajoja turėti špicų veislės šunį. Renkame pinigus, kad galėtume nusipirkti šunį ir juo rūpintis." },
    { id: 'p9', lt: "Man patinka gyventi Vilniuje. Tai gražus ir saugus miestas. Čia patogu auginti vaikus. Vilniuje gyvena geri ir draugiški žmonės. Visada galiu paprašyti pagalbos ir gauti pagalbą bei palaikymą. Nesijaučiu vieniša. Turiu daug pažįstamų ir draugų. Mokausi lietuvių kalbos, kad mano pažįstamų ratas būtų dar platesnis." },
  ],
  'parduotuve': [
    { id: 'p1', lt: "Kiekvieną sekmadienį mes su vyru automobiliu važiuojame į didelį prekybos centrą netoli mūsų namų. Mūsų šeimą sudaro keturi žmonės: aš, vyras ir du vaikai. Mums reikia daug maisto produktų visai savaitei." },
    { id: 'p2', lt: "Prieš važiuojant visada surašau pirkinių sąrašą. Sąraše būna:\nVaisiai ir daržovės: obuoliai, bananai, apelsinai, pomidorai, agurkai, bulvės, morkos, svogūnai, česnakai, žaliosios lapinės salotos ir bazilikai.\nPieno produktai: pienas, jogurtas, sūris, varškė.\nMėsa ir žuvis: vištiena, kalakutiena, jautiena, kiauliena, žuvis.\nDuona ir kruopos: balta ir juoda duona, ryžiai, makaronai, grikiai.\nGėrimai: mineralinis gazuotas ir negazuotas vanduo, sultys, gira.\nKiti produktai: kiaušiniai, aliejus, cukrus, druska, arbata, kava." },
    { id: 'p3', lt: "Parduotuvėje pasiimame vežimėlį ir einame apsipirkti. Pirmiausia einame į vaisių ir daržovių skyrių. Po to – į pieno produktų skyrių. Po to – į mėsos ir žuvies skyrius. Vaikai labai mėgsta valgyti kiaulienos šonkauliukus. Aš perku vištieną, kad galėčiau virti sriubas. Mes su vyru mėgstame šamo ir lašišos filė. Pakeliui į duonos ir kruopų skyrių pasiimame dar šaldytų produktų: ledų, žaliųjų pupelių, spinatų, bulvyčių gruzdinimui, koldūnų ir blynelių su varške. Mes labai mėgstame lietuvišką duoną. Mes perkame juodą duoną su saulėgrąžų sėklomis, batoną ir baltą duoną skrudinimui. Galiausiai buities prekių skyriuje pasiimame muilo, šiukšlių maišų, tualetinio popieriaus." },
    { id: 'p4', lt: "Mes niekada neperkame saldžiųjų gazuotų gėrimų, traškių kukurūzų lazdelių ir saldainių. Šie produktai labai kenkia mūsų dantims. Mes stengiamės valgyti sveiką ir naudingą maistą. Daug gaminame patys namuose, kad valgytume maistą be kenksmingų priedų." },
    { id: 'p5', lt: "Kai susirenkame pilną krepšį ir žinome, kad jame yra viskas, ko reikia iš mūsų sąrašo, einame prie kasos. Kasininkas nuskenuoja prekes ir mes susimokame. Paprastai mokame kortele." },
    { id: 'p6', lt: "Po parduotuvės važiuojame namo ir susidėliojame produktus. Vaikai mums padeda. Vaisius ir daržoves dedame į šaldytuvą, pieno produktus – taip pat į šaldytuvą, mėsą ir žuvį – į šaldiklį. Duoną ir kruopas dedame į spintelę. Kitas prekes dedame į jų vietas." },
    { id: 'p7', lt: "Mums patinka kartu važiuoti į parduotuvę. Tai padeda mums sutaupyti laiko ir pinigų." },
    { id: 'p8', lt: "Vyro biuras yra netoli Kalvarijų turgaus. Vasarą per pietų pertrauką vyras nueina į turgų. Jis perka šviežių braškių, avienčių, mėlynių ir šilauogių. Taip pat dažnai nusiperkame vyšnių, trešnių, raudonųjų ir juodųjų serbentų. Verdame kompotus iš šviežių uogų ir vaisių. Turguje galima nusipirkti didelių saldžių apelsinų ir sultingą ananasą." },
    { id: 'p9', lt: "Mes neperkame turguje mėsos produktų ar drabužių. Šias prekes nusiperkame prekybos centruose. Drabužius ir batus perkame sezono pradžioje ir dėvime labai ilgai, kad sutaupytume pinigų ir tausotume aplinką." },
  ],
  'sportas': [
    { id: 'p1', lt: "Mūsų šeima mėgsta sportą. Mes visi sportuojame, ir tai padeda mums būti sveikiems ir stipriems." },
    { id: 'p2', lt: "Mano vyras du kartus per savaitę lanko sporto klubą. Jis treniruojasi su treniruokliais ir daro pratimus su hanteliais. Jis nori būti stiprus ir sveikas. Mums su vyru jau keturiasdešimt metų. Šiame amžiuje svarbu daug judėti ir stiprinti raumenis." },
    { id: 'p3', lt: "Aš daug dirbu prie kompiuterio. Dažnai pavargsta nugara ir kaklas. Darbo metu darau trumpas pertraukas, kad atlikčiau nugaros raumenų stiprinimo pratimus. Tokius pratimus galima daryti stovint biure. Keliu ir nuleidžiu rankas, lenkiu kūną į skirtingas puses, suku galvą aukštyn, žemyn, į dešinę ir į kairę. Kasdien darau pratimus namuose, kad neskaudėtų nugaros." },
    { id: 'p4', lt: "Vasarą aš bėgioju parke. Tokia veikla stiprina širdį." },
    { id: 'p5', lt: "Mūsų sūnus žaidžia futbolą. Jis du kartus per savaitę lanko treniruotes ir savaitgaliais dalyvauja varžybose. Jis mėgsta futbolą ir nori tapti profesionaliu futbolininku." },
    { id: 'p6', lt: "Kartą per metus per televiziją žiūrime Pasaulio futbolo čempionato varžybas. Tai labai jaudinantis reginys. Kartais vyras darbe gauna nemokamus bilietus į krepšinio varžybas. Einame palaikyti naujos komandos „Wolves“ – vilkai. Tai jauna komanda, bet ji jau aktyviai varžosi su patyrusiomis Lietuvos komandomis, įskaitant žinomą komandą „Rytas“." },
    { id: 'p7', lt: "Mūsų dukra užsiima dailiuoju čiuožimu ir jodinėja žirgais. Ji du kartus per savaitę lanko dailiojo čiuožimo treniruotes. Vieną pamoką ji lanko su grupe. Per antrą pamoką ji treniruojasi su treneriu individualiai, kad išmoktų naujų dailiojo čiuožimo elementų. Šeštadieniais ji lanko jodinėjimo pamokas. Ji labai myli žirgus. Prieš pamoką ji šukuoja žirgą, kuriuo jodinės. O po pamokos valo jam kanopas ir maitina. Ji jau kelis kartus krito nuo žirgo. Bet vis tiek tęsia toliau. Aš didžiuojuosi tuo, kokia ji drąsi ir atkakli." },
    { id: 'p8', lt: "Kartais sekmadieniais einame į sporto centrą. Mes plaukiojame baseine ir šildomės saunoje. Mums patinka plaukioti kartu. Mokome vaikus nardyti ir plaukti skirtingomis technikomis. Neseniai nupirkome vaikams plaukmenis. Dabar jie yra greičiausi plaukikai baseine." },
    { id: 'p9', lt: "Manome, kad sportas yra labai svarbus. Jis padeda mums būti sveikiems, stipriems ir laimingiems." },
  ],
  'jura': [
    { id: 'p1', lt: "Lietuva yra nedidelė šalis, bet jos gamta graži ir įvairi. Lietuvos gyventojai gali ilsėtis ir prie jūros, ir miške, ir prie ežero." },
    { id: 'p2', lt: "Žiemą mūsų šeima mažai keliauja ir daug laiko praleidžia mieste. Mes rogutėmis leidžiamės nuo kalno šalia mūsų namų ir einame čiuožinėti į Rotušės aikštę." },
    { id: 'p3', lt: "Vasarą mūsų šeima mėgsta ilsėtis gamtoje. Mes dažnai važiuojame prie jūros, į parką ar prie ežero." },
    { id: 'p4', lt: "Labiausiai mums patiko poilsis prie jūros Palangoje. Mėgstame važiuoti prie jūros, nes ten grynas oras ir labai gražu. Mėgstame pušyną Baltijos jūros pakrantėje. Jūra mėlyna, o paplūdimys baltas. Mes maudomės jūroje, deginamės paplūdimyje ir statome smėlio pilis. Valgome ledus ir geriame limonadą. Vakare žiūrime iš Palangos pirso saulėlydį." },
    { id: 'p5', lt: "Palangoje yra labai gražus botanikos parkas su grafo Tiškevičiaus rūmais. Rūmuose yra Gintaro muziejus. Gintaro galima rasti vaikštant Baltijos jūros paplūdimiais. Yra graži legenda apie jūros deivę Jūratę. Lietuviai tiki, kad gintaras – tai deivės Jūratės ašaros. Ji liūdi dėl žuvusio mylimojo." },
    { id: 'p6', lt: "Parke taip pat labai gražu. Ten daug medžių ir gėlių, skulptūrų ir fontanų. Prie Tiškevičiaus rūmų yra puikus rožynas. Yra medžių, kuriems jau daugiau nei 100 metų. Parke yra pliažas ir pėsčiųjų ir dviračių takų, todėl galima vaikščioti arba važinėti dviračiais. Čia mes rengiame iškylas ir žaidžiame badmintoną. Valgome sumuštinius ir geriame arbatą." },
    { id: 'p7', lt: "Gyvename Vilniuje, todėl prie jūros važiuojame retai. Daug dažniau būname prie ežero. Vilniečiai labai mėgsta ilsėtis prie Žaliųjų ežerų. Ten yra didelis paplūdimys su gultais ir kavinėmis. Bet man ten nepatinka. Ši vieta yra toli nuo mūsų namų. Į paplūdimį atvažiuoja labai daug žmonių. Mėgstu ilsėtis mažuose, ramiuose paplūdimiuose. Vasarą su vaikais važiuojame maudytis prie Gelūžės ežero. Ten yra mūsų mėgstamas paplūdimys su kaukazinės slyvos medžiu. Ilsimės to medžio pavėsyje." },
    { id: 'p8', lt: "Prie ežero mėgstame maudytis ir degintis. Žaidžiame tinklinį ir kitus žaidimus su kamuoliu. Valgome šašlykus ir geriame sultis. Šalia paplūdimio stovi kioskas, kuriame galima nusipirkti ledų, pyragėlių su grybais ir bulvėmis bei kakavos. Kartais prie kranto atplaukia antys ir gulbės. Mes mėgstame stebėti šiuos gražius paukščius." },
    { id: 'p9', lt: "Mėgstame ilsėtis gamtoje. Tai padeda mums atsipalaiduoti ir pailsėti nuo miesto šurmulio." },
  ],
  'sveikata': [
    { id: 'p1', lt: "Stengiuosi rūpintis savo sveikata. Turiu galvą, kaklą, rankas, kojas ir kitas kūno dalis. Noriu, kad jos būtų sveikos. Todėl laikausi higienos. Kiekvieną rytą valau dantis ir einu į dušą. Prieš valgydama visada plaunu rankas. Stengiuosi sveikai maitintis. Valgau daug vaisių ir daržovių. Taip pat sportuoju. Mėgstu bėgioti ir plaukioti." },
    { id: 'p2', lt: "Kartais sekmadieniais mūsų šeima eina plaukioti į sporto centrą. Plaukiojame baseine ir šildomės pirtyje. Mums patinka plaukioti kartu. Mokome vaikus nardyti ir plaukioti įvairiomis technikomis. Neseniai nupirkome vaikams plaukmenis. Dabar jie yra greičiausi plaukikai baseine." },
    { id: 'p3', lt: "Manome, kad sportas yra labai svarbus. Jis padeda mums būti sveikiems, stipriems ir laimingiems." },
    { id: 'p4', lt: "Kartais jaučiuosi blogai. Pavyzdžiui, vakar man skaudėjo galvą. Maniau, kad peršalau. Man taip pat skaudėjo gerklę ir buvo sloga. Jaučiausi pavargusi. Nėjau į darbą. Likau namuose gulėti lovoje. Gėriau daug arbatos su citrina ir medumi bei avieičių uogienės gėrimą. Taip pat išgėriau vaistų nuo peršalimo. Šiandien jaučiuosi daug geriau. Jaučiu kvapus ir skonius. Man neskauda akių, ausų ir galvos. Jaučiuosi energinga." },
    { id: 'p5', lt: "Neseniai man suskaudo dantį. Paskambinau į odontologijos kliniką, kurioje paprastai lankausi. Administratorė pasiūlė man atvykti darbo dienos pabaigoje. Mano odontologas turėjo laisvo laiko 17 (septynioliktą) valandą. Baigusi darbą, nuvažiavau pas odontologą. Gydytojas padarė man rentgeno nuotrauką ir pasakė, kad man atskilo plomba. Ir man atsirado kariesas. Tačiau pažeidimas buvo nedidelis. Neturiu alergijos vaistams. Man padarė anesteziją. Per dvidešimt minučių odontologas pašalino seną plombą, išvalė kariesą ir įdėjo naują plombą. Turiu sveikatos draudimą. Tačiau lankausi privačiame odontologijos kabinete. Todėl už gydymą sumokėjau šimtą trisdešimt penkis eurus." },
    { id: 'p6', lt: "Turiu lėtinę ligą. Kiekvienais metais atlieku kraujo tyrimus ir man daro skydliaukės ultragarsinį tyrimą. Šie tyrimai apmokami iš ligonių kasos. Man taip pat nemokamai išduoda vaistinėje reikiamą vaistą, kurį geriu kasdien." },
    { id: 'p7', lt: "Mėgstu užsiimti joga. Darau tempimo pratimus, keliu rankas aukštyn ir leidžiu žemyn, sukuosi ir lenkiuosi. Galiu daryti viską, ką noriu. Tačiau kai sergu, jaučiuosi silpna. Negaliu nieko daryti. Tiesiog guliu lovoje." },
    { id: 'p8', lt: "Tikiuosi, kad visada liksiu sveika. Noriu gerai jaustis ir būti energinga. Noriu sportuoti ir keliauti. Noriu mėgautis gyvenimu!" },
  ],
  'ziema': [
    { id: 'p1', lt: "Žiemos atostogos yra mano mėgstamiausias metų laikas. Lietuvoje žiemą labai gražu. Visur balta nuo sniego, o miestas atrodo kaip iš pasakos. Šiemet žiema atėjo tik sausį. Bet mes spėjome pasidžiaugti žiemos pramogomis." },
    { id: 'p2', lt: "Vilniuje, Rotušės aikštėje, yra čiuožykla. Ten galima čiuožinėti ir linksmintis su draugais." },
    { id: 'p3', lt: "Vilniaus parkuose galima slidinėti. Mes rogutėmis leidomės nuo kalno šalia mūsų namų ir žaidėme sniego gniūžtėmis. Kai prisnigo daug sniego, mes kartu su kaimynais pastatėme didelę sniego tvirtovę. Šalia tvirtovės nulipdėme sniego senį, kad jis saugotų tvirtovę. Vaikai labai džiaugėsi." },
    { id: 'p4', lt: "Gruodį Vilniuje ir kituose Lietuvos miestuose atidaromos Kalėdų mugės. Ten galima nusipirkti dovanų, paragauti skanaus maisto ir išgerti karšto šokolado. Mes buvome Kalėdų mugėje prie Katedros aikštės. Grožėjomės pagrindine Lietuvos Kalėdų eglute. Vakare prie Kalėdų eglutės vyksta šventinis koncertas. Miestiečiai mėgsta šokti ir klausytis linksmos muzikos." },
    { id: 'p5', lt: "Žiemą gera lankytis muziejuose. Vilniuje yra daug įdomių muziejų. Mano vaikai labai mėgsta Energetikos ir technikos muziejų, kur galima nusileisti nuo kalnelio iš viršutinio aukšto į apatinį ir sužinoti, kokiu greičiu nusileidai. Visiems mokiniams patariame aplankyti interaktyvią ekspoziciją „Technikos mokslas ir technika vaikams“." },
    { id: 'p6', lt: "Vilniaus senamiestis žiemą atrodo ypač gražiai. Galima vaikščioti siauromis gatvelėmis, apžiūrinėti senovinius pastatus ir gerti karštą arbatą kavinėje." },
    { id: 'p7', lt: "Prie Ozo prekybos centro yra didelis vandens parkas. Jame galima plaukioti baseinuose, leistis nuo kalnelių ir ilsėtis saunoje." },
    { id: 'p8', lt: "Per žiemos atostogas mūsų šeima paprastai lieka Vilniuje. Mėgstame vaikščioti po miestą, čiuožinėti ir eiti į kiną. Kartais su šeima važiuojame į Druskininkus paslidinėti ir aplankyti vandens parką." },
    { id: 'p9', lt: "Man patinka žiemos atostogos Lietuvoje. Tai laikas, kai galima pailsėti, pasilinksminti ir pasidžiaugti žiemos gamtos grožiu." },
  ],
  'sventes': [
    { id: 'p1', lt: "Lietuva yra turtingos istorijos ir kultūros šalis. Per metus lietuviai švenčia daug valstybinių švenčių, susijusių su istorija, tradicijomis ir religija. Sausio 1 (pirmą) dieną švenčiami Naujieji metai. Tačiau lietuviams šį šventę nėra tokia svarbi, kaip Kalėdos." },
    { id: 'p2', lt: "Vasario 16 (šešioliktą) dieną lietuviai švenčia Lietuvos valstybės atkūrimo dieną. Ši šventė mini Lietuvos Nepriklausomybės Akto pasirašymą 1918 (tūkstantis devyni šimtai aštuonioliktais) metais. Tai labai svarbi šventė lietuviams. Tą dieną visoje šalyje vyksta iškilmingi renginiai, koncertai ir paradai." },
    { id: 'p3', lt: "Kovo 11 (vienolikta) – Lietuvos nepriklausomybės atkūrimo diena. Ši šventė mini Lietuvos nepriklausomybės atkūrimą 1990 (tūkstantis devyni šimtai devyniasdešimtais) metais. Tą dieną taip pat vyksta iškilmingi renginiai ir koncertai." },
    { id: 'p4', lt: "Velykos arba Kristaus prisikėlimas – seniausia ir svarbiausia krikščionių šventė. Minimas Kristaus prisikėlimas iš numirusiųjų po nukryžiavimo, kuris laikomas viso krikščioniškojo mokymo pagrindu." },
    { id: 'p5', lt: "Gegužės 1 (pirma) – Tarptautinė darbo diena. Šios šventės metu siekiama atkreipti dėmesį į darbininkų teises, padėti pasirūpinti darbininkų sauga ir sveikata." },
    { id: 'p6', lt: "Birželio 24 (dvidešimt ketvirta) – Rasos ir Joninių diena. Rasos – senoji lietuvių pagoniška vasaros saulėgrįžos šventė, vėliau sutapatinta su šventojo Jono diena ir pavadinta Joninėmis. Tą dieną žmonės degina laužus, pina vainikus iš gėlių ir žolelių, ieško paparčio žiedo. Mūsų šeima mėgsta švęsti šią šventę Kernavėje. Ten yra etnografinis muziejus su įvairia ekspozicija. Per Jonines galima pasiklausyti tradicinių lietuvių dainų, pašokti tradicinių šokių, nusipirkti ką nors įdomaus ir naudingo mugėje." },
    { id: 'p7', lt: "Rugpjūčio 15 (penkiolikta) diena – katalikiška šventė Žolinė (Švenčiausios Mergelės Marijos ėmimo į dangų diena). Lietuvoje liaudiškas šios šventės pavadinimas – Žolinė, kadangi per iškilmingas šventės Mišias šventinami žolynai." },
    { id: 'p8', lt: "Liepos 6 d. – Valstybės (Lietuvos karaliaus Mindaugo karūnavimo) ir Tautiškos giesmės diena. Ši šventė mini pirmojo ir vienintelio Lietuvos karaliaus Mindaugo karūnavimą 1253 (tūkstantis du šimtai penkiasdešimt trečiais) metais. Kasmet liepos 6 (šeštą) dieną 21 (dvidešimt pirmą) valandą viso pasaulio lietuviai raginami vienybės vardan sugiedoti „Tautišką giesmę“." },
    { id: 'p9', lt: "Lapkričio 1 (pirma) diena – Visų Šventųjų diena. Ir lapkričio 2 (antra) diena - Vėlinės – mirusiųjų atminimo ir pagerbimo diena. Tomis dienomis lietuviai lanko kapines, kad pagerbtų mirusių giminių ir artimųjų atminimą. Lietuvių tradicija - prieš tas dienas sutvarkyti kapus ir ant kiekvieno kapo uždegti žvakių." },
    { id: 'p10', lt: "Gruodžio 24 (dvidešimt ketvirtą) dieną švenčiamos Kūčios, o 25 (dvidešimt penktą) dieną – Kalėdos. Dabar Kūčios paprastai yra šeimos ar artimiausių draugų vakarienė. Kūčioms nuo seno gamindavo 12 ar 13 patiekalų. Senais laikais per Kūčias buvo buriama ir prisimenami protėviai. Kalėdos Lietuvoje – tai šeimos šventė, kai žmonės susirenka kartu švęsti Kristaus gimimą ir keistis dovanomis." },
    { id: 'p11', lt: "Lietuvos nacionalinės šventės yra svarbi šalies kultūros paveldo dalis. Jos padeda lietuviams išsaugoti savo tapatybę ir tradicijas." },
  ],
};

